    for (int i = 0; i < n; i++) {
        const string& op = ops[i][0];
        if (op == "add") {
            left += ops[i][1];
        } else if (op == "delete") {
            size_t k = min((size_t) stoll(ops[i][1]), left.size());
            left.resize(left.size() - k);
